118	function initialsOf(name: string): string {
119	  const parts = String(name ?? "")
120	    .trim()
121	    .split(/\s+/)
122	    .filter((p) => /^[a-z0-9]/i.test(p));
123	  if (parts.length === 0) return "TP";
